export function phaseFourLocaleContent(locale: Locale): Partial<Record<Slug, LocalizedCalculatorContent>> {
  const rows = copies[locale];
  return Object.fromEntries(phaseFourTranslatedCalculatorSlugs.map((slug) => {
    const page = getCalculatorPage(slug);
    const index = phaseFourTranslatedCalculatorSlugs.indexOf(slug);
    const bundle = bundles[locale];
    const copy = rows[slug] ?? (bundle ? {
      name: bundle.names[index]!, description: bundle.descriptions[index]!, guide: bundle.guides[index]!, formula: bundle.formulas[index]!,
      example: bundle.examples[index]!, faqs: bundle.faqs,
      policy: bundle.policy,
      fields: bundle.labels,
      options: bundle.options,
      results: Object.fromEntries(Object.keys(copies.ko[slug]?.results ?? {}).map((label, resultIndex) => [label, bundle.labels[label] ?? (translatedResultLabels[locale]?.[index]?.[resultIndex] ?? bundle.results?.[index]?.[resultIndex] ?? resultNames[locale as keyof typeof resultNames]?.[Math.min(resultIndex, 4)] ?? label)])),
    } satisfies Copy : undefined);
    if (!page || !copy) throw new Error(`Missing Japan calculator translation: ${locale}:${slug}`);
    const localUnits: Record<Locale, { yen: string; hour: string }> = { ko: { yen: "엔", hour: "시간" }, en: { yen: "yen", hour: "hours" }, ja: { yen: "円", hour: "時間" }, zh: { yen: "日元", hour: "小时" }, es: { yen: "yenes", hour: "horas" }, "pt-br": { yen: "ienes", hour: "horas" }, de: { yen: "Yen", hour: "Stunden" }, fr: { yen: "yens", hour: "heures" }, vi: { yen: "yên", hour: "giờ" }, id: { yen: "yen", hour: "jam" }, th: { yen: "เยน", hour: "ชั่วโมง" }, "zh-tw": { yen: "日圓", hour: "小時" }, it: { yen: "yen", hour: "ore" }, nl: { yen: "yen", hour: "uur" }, hi: { yen: "येन", hour: "घंटे" } };
    const fields = Object.fromEntries(page.fields.map((field) => [field.name, { label: copy.fields[field.name] ?? field.label, ...(field.placeholder ? { placeholder: copy.fields[field.name] ?? field.label } : {}), ...(field.unit ? { unit: field.unit === "円" ? localUnits[locale].yen : field.unit === "時間" ? localUnits[locale].hour : field.unit } : {}) }]));
    const options = Object.fromEntries(page.fields.filter((field) => field.options).map((field) => [field.name, Object.fromEntries(field.options!.map((option) => [option.value, copy.options[option.value] ?? option.label]))]));
    const resultLabels = copy.results;
    const related = page.relatedCalculatorIds as LocalizedCalculatorContent["related"];
    const suffix = locale === "ja" ? "計算・目安" : locale === "en" ? "Japan estimate" : locale === "zh" ? "日本参考计算" : locale === "zh-tw" ? "日本參考計算" : locale === "es" ? "estimación de Japón" : locale === "pt-br" ? "estimativa para o Japão" : locale === "de" ? "Japan-Schätzung" : locale === "fr" ? "estimation pour le Japon" : locale === "vi" ? "ước tính tại Nhật Bản" : locale === "id" ? "estimasi Jepang" : locale === "th" ? "ประมาณการตามเกณฑ์ญี่ปุ่น" : locale === "it" ? "stima per il Giappone" : locale === "nl" ? "schatting voor Japan" : locale === "hi" ? "जापान का अनुमान" : "일본 기준 참고 계산";
    return [slug, { name: copy.name, shortName: copy.name, title: `${copy.name} | ${suffix}`, description: copy.description, keywords: [copy.name, ...page.keywords.slice(0, 2)], howTo: `${copy.guide} ${copy.policy}`, formula: copy.formula, example: copy.example, faqs: copy.faqs, related, fields, options, resultLabels, validation: locale === "ja" ? "入力内容を確認してください。" : locale === "en" ? "Check the entered values and try again." : locale === "zh" ? "请检查输入内容后重试。" : locale === "zh-tw" ? "請確認輸入內容後再試一次。" : locale === "es" ? "Revisa los datos y vuelve a intentarlo." : locale === "pt-br" ? "Confira os dados e tente novamente." : locale === "de" ? "Bitte überprüfe die Eingaben und versuche es erneut." : locale === "fr" ? "Vérifiez les valeurs saisies puis réessayez." : locale === "vi" ? "Vui lòng kiểm tra dữ liệu đã nhập và thử lại." : locale === "id" ? "Periksa nilai yang dimasukkan lalu coba lagi." : locale === "th" ? "โปรดตรวจสอบค่าที่ป้อนแล้วลองอีกครั้ง" : locale === "it" ? "Controlla i valori inseriti e riprova." : locale === "nl" ? "Controleer de ingevoerde waarden en probeer het opnieuw." : locale === "hi" ? "दर्ज किए गए मान जाँचें और फिर कोशिश करें।" : "입력값을 확인해 주세요.", resultNote: copy.policy } satisfies LocalizedCalculatorContent];
  })) as Partial<Record<Slug, LocalizedCalculatorContent>>;
}
